using EventModel.Domain;

namespace EventModel.Domain.OrderAggregate;

/// Pure decision functions. No I/O, no framework — the whole point.
public static class OrderDecider
{
    /// Slice: place-order — PlaceOrder emits OrderPlaced.
    public static IReadOnlyList<object> Decide(OrderState state, PlaceOrder command, DateTimeOffset now)
    {
        if (command.TotalAmount <= 0)
            throw new RejectionException("EmptyOrder", "totalAmount <= 0");

        return new object[]
